import heapq


def shortest_path(edges, start, end):
    # Check for negative weights
    for _, _, w in edges:
        if w < 0:
            raise ValueError("Negative weight detected")

    # If start and end are the same
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = {}
    for frm, to, w in edges:
        if frm not in graph:
            graph[frm] = []
        graph[frm].append((to, w))

    # Dijkstra's algorithm
    dist = {start: 0}
    prev = {start: None}
    heap = [(0, start)]
    visited = set()

    while heap:
        current_dist, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)

        if u == end:
            # Reconstruct path
            path = []
            node = end
            while node is not None:
                path.append(node)
                node = prev[node]
            path.reverse()
            return (current_dist, path)

        for v, w in graph.get(u, []):
            if v in visited:
                continue
            new_dist = current_dist + w
            if v not in dist or new_dist < dist[v]:
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(heap, (new_dist, v))

    # No path found
    return (None, None)
